const lead = $json;
let sendEligibility;
if (!lead.lead_id) {
  // GS - Load Lead Record found nothing for this lead_id (alwaysOutputData emitted an empty item).
  sendEligibility = 'missing';
} else if (lead.status && lead.status !== 'New submission') {
  // Spec 13.1 idempotency: before sending, check whether the same template/step was already
  // successfully sent. The Leads.status column is the single source of truth (spec 3.2), not
  // execution history, so a status other than 'New submission' means WF-02 already ran for
  // this lead (or it moved further down the funnel) and must not send a second result email.
  sendEligibility = 'already_sent';
} else {
  sendEligibility = 'eligible';
}
return [{ json: { ...lead, send_eligibility: sendEligibility } }];

const lead = $('GS - Load Lead Record').first().json;
const configRows = $('GS - Load Config').all();
const templateRows = $('GS - Load Email Templates').all();

const config = {};
for (const row of configRows) {
  const key = row.json.Key ?? row.json.key;
  const value = row.json.Value ?? row.json.value;
  if (key) config[key] = value;
}

let weakestCategories = [];
if (Array.isArray(lead.weakest_categories)) {
  weakestCategories = lead.weakest_categories;
} else {
  try { weakestCategories = JSON.parse(lead.weakest_categories || '[]'); } catch { weakestCategories = []; }
}

// Spec section 10.5 recommendation library, keyed by the same category labels CODE -
// Calculate Scores in WF-01 writes into weakest_categories.
const recommendationLibrary = {
  'Lead centralization': 'Route website, advertising, portal and call leads into one controlled lead record.',
  'Response speed': 'Send immediate acknowledgement and create a timed assignment/escalation process.',
  'Lead assignment': 'Apply automatic routing by location, service, availability or round-robin rules.',
  'Follow-up': 'Create a consistent multi-step sequence with tasks, SMS/email and stop conditions.',
  'Missed calls': 'Trigger a compliant text-back or callback task and record it against the lead.',
  'Management visibility': 'Create a dashboard for response, contact, appointment, conversion and lost reasons.',
  'Lead storage': 'Remove duplicate entry by connecting forms and channels to the primary CRM.'
};

const weaknesses = weakestCategories.map((w) => ({
  category: w.category,
  score: w.score,
  recommendation: recommendationLibrary[w.category] || 'Review and document this process step by step.'
}));

const firstName = (lead.name || '').trim().split(/\s+/)[0] || '';
const grade = (lead.lead_grade || '').toUpperCase();
const templateId = grade === 'A' ? 'result_email_a' : grade === 'B' ? 'result_email_b' : 'result_email_c';
const template = templateRows.map((r) => r.json).find((r) => (r.template_id ?? r.Template_ID) === templateId);

if (!template) {
  throw new Error(`WF-02: No Email_Templates row found for template_id "${templateId}". Add it to the Email_Templates tab before sending.`);
}

// Appends client_type onto the Cal.com booking link as the prefill value for that event
// type's 'client_type' custom question (see WF-05's CODE - Normalize Booking Payload) - this
// is how a booking made from this email round-trips back to the correct client spreadsheet
// without the lead ever seeing or touching that field.
const clientType = $('TRG - Execute Workflow Trigger').last().json.type || '';
const rawBookingUrl = config.BOOKING_URL || '';
const bookingUrl = rawBookingUrl
  ? `${rawBookingUrl}${rawBookingUrl.includes('?') ? '&' : '?'}client_type=${encodeURIComponent(clientType)}`
  : '';

// Token names match the literal {{...}} placeholders in the approved Email_Templates copy
// exactly (spec section 9 / the Email_Templates tab), not the wording used anywhere else.
const tokens = {
  'First Name': firstName,
  'Company Name': lead.company_name || '',
  'System Health Score': lead.system_health_score,
  'Weakness 1': weaknesses[0]?.category || '',
  'Weakness 2': weaknesses[1]?.category || '',
  'Weakness 3': weaknesses[2]?.category || '',
  'Recommendation 1': weaknesses[0]?.recommendation || '',
  'Main Problem': lead.main_problem || '',
  'Booking URL': bookingUrl,
  'Sender Name': config.SENDER_NAME || 'The Magnetar Solutions Team'
};

function fillTemplate(str, map) {
  // Live testing (2026-07-31) found the actual Email_Templates sheet uses inconsistent
  // token casing between fields (e.g. subject: '{{company_name}}', body: '{{Company Name}}'
  // for the same template row) - a plain exact-string lookup left the subject's token
  // unsubstituted in the email a real prospect received. Normalize both sides so casing,
  // underscores and spacing in the sheet never matter.
  const normalize = (s) => String(s).toLowerCase().replace(/[_\s]+/g, ' ').trim();
  const normalizedMap = {};
  for (const k in map) normalizedMap[normalize(k)] = map[k];
  return String(str ?? '').replace(/\{\{\s*([^}]+?)\s*\}\}/g, (match, key) => {
    const normalizedKey = normalize(key);
    return Object.prototype.hasOwnProperty.call(normalizedMap, normalizedKey) ? String(normalizedMap[normalizedKey] ?? '') : match;
  });
}

const emailSubject = fillTemplate(template.subject, tokens);
const emailBody = fillTemplate(template.body, tokens);

return [{ json: {
  ...lead,
  config,
  weaknesses_with_recommendations: weaknesses,
  first_name: firstName,
  email_subject: emailSubject,
  email_body: emailBody
} }];

const lead = $json;
const stripCRLF = (s) => String(s ?? '').replace(/[\r\n]+/g, ' ').trim();

const to = stripCRLF(lead.work_email);
const subject = stripCRLF(lead.email_subject);
const body = String(lead.email_body ?? '');
const type = stripCRLF($('TRG - Execute Workflow Trigger').last().json.type);
const sheetId = stripCRLF($('TRG - Execute Workflow Trigger').last().json.sheet_id);

// RFC 2047-encode the subject in case it contains non-ASCII characters.
const encodedSubject = /[^\x00-\x7F]/.test(subject)
  ? `=?UTF-8?B?${Buffer.from(subject, 'utf-8').toString('base64')}?=`
  : subject;

// X-Client-Type/X-Client-Sheet-Id let WF-06 resolve which client's spreadsheet a reply
// belongs to (via the original message's headers, looked up by In-Reply-To) without having
// to search every client folder. stripCRLF on every interpolated value prevents header
// injection, since work_email/type ultimately trace back to untrusted form input in WF-01.
const headers = [
  `To: ${to}`,
  `Subject: ${encodedSubject}`,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset="UTF-8"',
  `X-Client-Type: ${type}`,
  `X-Client-Sheet-Id: ${sheetId}`
];

const rawMessage = headers.join('\r\n') + '\r\n\r\n' + body;
const encoded = Buffer.from(rawMessage, 'utf-8').toString('base64')
  .replace(/\+/g, '-')
  .replace(/\//g, '_')
  .replace(/=+$/, '');

return [{ json: { ...lead, raw: encoded } }];

const sendResult = $input.first().json;
const built = $('CODE - Build Result Email').first().json;

return [{ json: {
  lead_id: built.lead_id,
  work_email: built.work_email,
  lead_grade: built.lead_grade,
  message_id: sendResult.id || '',
  thread_id: sendResult.threadId || '',
  subject: built.email_subject,
  sent_at_utc: new Date().toISOString(),
  delivery_status: 'sent'
} }];

const sent = $('CODE - Record Send Result').first().json;
return [{ json: {
  lead_id: sent.lead_id,
  email_delivered: true,
  message_id: sent.message_id,
  delivery_status: sent.delivery_status
} }];

const item = $json;
return [{ json: {
  lead_id: item.lead_id,
  email_delivered: false,
  message_id: '',
  delivery_status: 'skipped_duplicate'
} }];
